{
  "technical_and_design_decisions": [
    "Make Sqoop metastore pluggable via a Spring-configured interface, keeping the default but allowing custom DB implementations (U1).",
    "Document HDFS-backed module registry configuration in the existing project documentation format, referencing XD-2287 (U2).",
    "Extend the existing Metrics REST controller to add new endpoints that return all counters, gauges, and rich-gauges in single requests (U3).",
    "Implement ModuleRunner as a Spring Boot application that launches XD modules directly in a single process, removing the need for xd-containers (U4).",
    "Extend the GemFire (GF) source module to read native authentication and security properties from configuration and map them to the GF client (U5).",
    "Implement the jdbcgpfdist batch job as a Spring Batch job that reuses the existing gpfdist writer component to output to HAWQ/GPDB (U6).",
    "Refactor test infrastructure to define thin repository interfaces; provide mock implementations for unit tests and real implementations for integration tests (U7).",
    "Relocate the Reactor-based data processor module from the external repo into the core project, updating build files and package structure (U8).",
    "Use Java 17 and Spring Framework 6 baseline APIs for any new code, consistent with the specification's note on Spring 6."
  ],
  "assumptions": [
    "The user stories reference Spring XD concepts (xd-containers, module registry, XD-2287), so the work is within the Spring XD project, not the core Spring Framework described in the intro.",
    "The existing Spring XD codebase is available, builds, and has a test harness that can be refactored without rewriting all tests.",
    "The developer has adequate knowledge of Sqoop, GemFire, HAWQ/GPDB, and Project Reactor to implement the required changes.",
    "The existing gpfdist sink code can be adapted to a batch writer with minimal changes.",
    "New REST endpoints follow existing security, serialization, and URL patterns without requiring new authentication mechanisms.",
    "Documentation is limited to configuration and usage notes in the project's current docs format; no full manual rewrite is needed.",
    "The metrics repository already supports retrieving all metrics by type, so the REST layer is a thin wrapper.",
    "U4 scope is limited to single-node, container-managed execution as implied by the linked scope; distributed orchestration is out of scope.",
    "The Reactor module move does not require API changes, only relocation and build adjustments.",
    "Effort estimates exclude production deployment, user training, and post-release maintenance."
  ],
  "activities": [
    {
      "activity_id": "ACT-01",
      "activity_name": "Analysis and High-Level Design",
      "activity_description": "Analyze all 8 user stories, design pluggable metastore, REST endpoints, Boot ModuleRunner, GF auth, batch job, test infra interfaces, and module relocation plan.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "ACT-02",
      "activity_name": "U1: Configurable Sqoop Metastore",
      "activity_description": "Refactor Sqoop metastore access behind a configurable interface; provide default and allow custom DB implementation via Spring config; unit tests.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "ACT-03",
      "activity_name": "U2: HDFS Module Registry Documentation",
      "activity_description": "Write and update documentation describing how to configure HDFS-backed module registry as recommended in XD-2287.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-04",
      "activity_name": "U3: Bulk Metrics REST API",
      "activity_description": "Implement new REST endpoints (/metrics/counters/all, /metrics/gauges/all, /metrics/rich-gauges/all) returning all metrics of each type; unit tests.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "ACT-05",
      "activity_name": "U4: Boot-based ModuleRunner",
      "activity_description": "Develop Spring Boot-based ModuleRunner to execute XD modules in container-managed environments without xd-containers; integration tests.",
      "most_likely_effort": 48
    },
    {
      "activity_id": "ACT-06",
      "activity_name": "U5: GF Source Native Authentication",
      "activity_description": "Add native GemFire authentication support to GF source, including configuration properties and documentation of where to set them.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "ACT-07",
      "activity_name": "U6: jdbcgpfdist Batch Job",
      "activity_description": "Implement OOTB batch job reading from JDBC and writing to HAWQ/GPDB via gpfdist protocol, reusing existing gpfdist writer; unit/integration tests.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "ACT-08",
      "activity_name": "U7: Test Infrastructure Refactor",
      "activity_description": "Separate mock and real repository coupling by introducing thin interfaces and test configurations; update test support classes.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "ACT-09",
      "activity_name": "U8: Reactor Module Relocation",
      "activity_description": "Move Reactor-based data processor module from spring-xd-module repo into core, adjust build, dependencies, and package structure; verify tests.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "ACT-10",
      "activity_name": "Integration Testing and Build Verification",
      "activity_description": "Perform system integration testing across all new features, fix defects, ensure CI build passes.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "ACT-11",
      "activity_name": "Documentation Review and Finalization",
      "activity_description": "Review all documentation changes, ensure consistency, and finalize user guides.",
      "most_likely_effort": 8
    }
  ],
  "reported_total": {
    "most_likely_effort": 252
  }
}

